// ============ 这个例子特意留了个陷阱 ============
//
// 顶点 3 直连源点的权值是 5，一眼看去答案就是 5。
// 但绕 1 → 2 → 3 走一圈只要 2 + 1 + 1 = 4。
//
// 这正是 Dijkstra 要处理的情况：**初始的 dist 只是"目前已知"，不是答案**，
// 必须靠一轮轮松弛把它改小。
//
// 如果程序输出 5 而不是 4，说明松弛那一步写错了 ——
// 最常见的原因是漏了 `<` 判断，或者只更新了 dist 忘了更新 path。

// 主函数
int main(void)
{
// 带权边表：每条边 { 起点, 终点, 权值 }
// 这张图的形状：
//          0 ──2── 1
//          │       │
//          5       1
//          │       │
//          3 ──1── 2
    static const int edges[][3] = { { 0, 1, 2 }, { 0, 3, 5 }, { 1, 2, 1 }, { 2, 3, 1 } };

// 图
    MGraph G;
// 三个结果数组
    int dist[MAXV];
    int path[MAXV];
// 源点
    int s = 0;
// 循环用
    int i, j;

// 建图
    CreateWeightedGraph(&G, 4, edges, 4);

// 打印邻接矩阵
    printf("带权图的邻接矩阵（%d 表示没有边）：\n", INF);
    printf("      ");
    for (j = 0; j < G.nv; j++)
    {
        printf("%6d", j);
    }
    printf("\n");

    for (i = 0; i < G.nv; i++)
    {
        printf("  %2d [", i);
        for (j = 0; j < G.nv; j++)
        {
            if (G.g[i][j] >= INF)
            {
                printf("%6s", "INF");
            }
            else
            {
                printf("%6d", G.g[i][j]);
            }
        }
        printf(" ]\n");
    }
    printf("（数出来的边数 = %d）\n\n", CountWeightedEdges(&G));

// 跑 Dijkstra
    Dijkstra(&G, s, dist, path);

// 打印结果
    PrintAll(&G, s, dist, path);

// 重点提示
    printf("\n注意顶点 3：直连源点的权值是 5，但绕 0→1→2→3 只要 4\n");
    printf("（这就是「松弛」要反复做的原因 —— 第一眼看到的未必最好）\n\n");

// 换个源点再跑一次
    printf("=== 换个源点：从 2 出发 ===\n");
    Dijkstra(&G, 2, dist, path);
    PrintAll(&G, 2, dist, path);

// 正常结束
    return 0;
}

