#include <stdio.h>
#include <stdlib.h>

/* ======== [已给出] 模块 01 typedef ======== */

#define MAXV 100

#define INF 65535

typedef struct
{
    int nv;
    int ne;
    int g[MAXV][MAXV];
} MGraph;

#define OK 1
#define ERROR 0
typedef int Status;

void CreateWeightedGraph(MGraph *G, int nv, const int edges[][3], int edgeCount)
{
    int i, j;

    G->nv = nv;
    G->ne = edgeCount;

    for (i = 0; i < nv; i++)
    {
        for (j = 0; j < nv; j++)
        {
            G->g[i][j] = (i == j) ? 0 : INF;
        }
    }

    for (i = 0; i < edgeCount; i++)
    {
        int u = edges[i][0];
        int v = edges[i][1];
        int w = edges[i][2];

        G->g[u][v] = w;
        G->g[v][u] = w;
    }
}

void InitDistPath(MGraph *G, int s, int dist[], int path[])
{
    int i;

    for (i = 0; i < G->nv; i++)
    {
        dist[i] = G->g[s][i];

        if (G->g[s][i] < INF && i != s)
        {
            path[i] = s;
        }
        else
        {
            path[i] = -1;
        }
    }

    dist[s] = 0;
    path[s] = -1;
}

/* ======== [已给出] 模块 02 FindMinDist ======== */

int FindMinDist(MGraph *G, int dist[], int collected[])
{
    int minV = -1;
    int minDist = INF;
    int i;

    for (i = 0; i < G->nv; i++)
    {
        if (collected[i] == 0 && dist[i] < minDist)
        {
            minDist = dist[i];
            minV = i;
        }
    }

    return minV;
}

int CountWeightedEdges(MGraph *G)
{
    int i, j;
    int count = 0;

    for (i = 0; i < G->nv; i++)
    {
        for (j = 0; j < G->nv; j++)
        {
            if (i != j && G->g[i][j] < INF)
            {
                count++;
            }
        }
    }

    return count / 2;
}

/* ======== [已给出] 模块 03 Dijkstra ======== */

void Dijkstra(MGraph *G, int s, int dist[], int path[])
{
    int collected[MAXV];
    int i;
    int v;
    int w;

    InitDistPath(G, s, dist, path);

    for (i = 0; i < G->nv; i++)
    {
        collected[i] = 0;
    }
    collected[s] = 1;

    while (1)
    {
        v = FindMinDist(G, dist, collected);

        if (v < 0)
        {
            break;
        }

        collected[v] = 1;

        for (w = 0; w < G->nv; w++)
        {
            if (collected[w] == 0 && G->g[v][w] < INF)
            {
                if (dist[v] + G->g[v][w] < dist[w])
                {
                    dist[w] = dist[v] + G->g[v][w];
                    path[w] = v;
                }
            }
        }
    }
}

/* ======== [已给出] 模块 04 PrintPath ======== */

void PrintPath(int path[], int v)
{
    if (path[v] >= 0)
    {
        PrintPath(path, path[v]);

        printf(" → %d", v);
    }
    else
    {
        printf("%d", v);
    }
}

void PrintAll(MGraph *G, int s, int dist[], int path[])
{
