modes.detail:
#include <stdio.h>
#include <stdlib.h>

// ============ 为什么用 INF 而不是 0 ============
//
// 无权图里 0 表示"没有边"，1 表示"有边"。但带权图不行了 ——
// **权值本身可能是 0**（比如"免费换乘"）。如果还用 0 表示无边，
// 就分不清"没有这条路"和"这条路不花钱"。
//
// 所以另设一个"不可能出现的权值"当标记：
//
//     #define INF 65535
//
// 只要保证所有真实权值都远小于它就行。这样判断"有没有边"就变成
// `g[i][j] < INF`。
//
// 一个常见的坑：INF 取太小（比如 32767）时，**两段 INF 相加会溢出**，
// 变成负数，于是 `dist[v] + g[v][w] < dist[w]` 这个判断就乱了。
// 所以取 65535 而不是更小的值，并且做加法前先确认它确实是条边。
//
// ============ 三个数组的分工 ============
//
//   dist[w]       源点到 w 的当前最短距离（会不断变小）
//   collected[w]  0 表示"还没确定"，1 表示"已经确定，不会再变了"
//   path[w]       w 的前驱，用来从终点倒着走回起点
//
// 注意 dist 和 collected 的分工：dist 是"目前看来最短的距离"，
// collected 才表示"这个距离已经是最终答案了"。
// 一开始只有源点自己的 dist 是确定的，其余都是"待定"。

// 最多顶点数
#define MAXV 100

// 表示"没有边"的权值
// 取一个大数，并且保证任何真实路径长度都远小于它的一半，
// 这样即使相加也不会溢出。
#define INF 65535

// 带权图的邻接矩阵
typedef struct
{
// 顶点数
    int nv;
// 边数
    int ne;
// g[i][j] 是边 i→j 的权值；等于 INF 表示没有这条边
    int g[MAXV][MAXV];
} MGraph;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// 用带权边表建图
// edges 每条边是 { 起点, 终点, 权值 }
void CreateWeightedGraph(MGraph *G, int nv, const int edges[][3], int edgeCount)
{
// 循环用
    int i, j;

// 记规模
    G->nv = nv;
    G->ne = edgeCount;

// 初始化：无边的地方填 INF，对角线填 0
// 对角线填 0 是"自己到自己的距离"，正好是 0，不用特判。
    for (i = 0; i < nv; i++)
    {
        for (j = 0; j < nv; j++)
        {
            G->g[i][j] = (i == j) ? 0 : INF;
        }
    }

// 逐条边填权值
    for (i = 0; i < edgeCount; i++)
    {
        int u = edges[i][0];
        int v = edges[i][1];
        int w = edges[i][2];

// 无向图两个方向都填
        G->g[u][v] = w;
        G->g[v][u] = w;
    }
}

// 初始化三个数组（供 Dijkstra 使用）
// 单独抽出来是因为"初始化"和"算法主体"是两件不同的事，
// 混在一起会让主循环难读。
void InitDistPath(MGraph *G, int s, int dist[], int path[])
{
// 循环用
    int i;

// dist 一开始只知道源点直连的那些边
    for (i = 0; i < G->nv; i++)
    {
        dist[i] = G->g[s][i];

// path：直连的记下源点，不直连的记 -1
// -1 表示"还不知道从哪儿来"。后面 PrintPath 就是靠它判断有没有到起点。
        if (G->g[s][i] < INF && i != s)
        {
            path[i] = s;
        }
        else
        {
            path[i] = -1;
        }
    }

// 源点到自己是 0
    dist[s] = 0;
// 源点的前驱是自己（也可以理解成"没有前驱"）
    path[s] = -1;
}

// ============ 这个函数在做什么 ============
//
// 每轮都要问一句：**剩下的待定顶点里，谁的 dist 最小？**
//
// 挑出来的那个就可以"转正"了 —— 它的 dist 就是最终答案。
//
// 返回 -1 表示"没有待定的了"，这时候主循环就该结束。
//
// ============ 为什么不直接遍历全部顶点 ============
//
// 因为已经收录的顶点**不该再参与比较** —— 它们的 dist 已经定了，
// 再挑一次没有意义，还可能把已经确定的顶点又"重新确定"一遍。
//
// 所以条件是 `!collected[i] && dist[i] < minDist`，两个都要。
//
// ============ 朴素实现是 O(n) ============
//
// 一次线性扫描是 O(n)，而主循环要跑 n 轮，所以整体是 **O(n²)**。
//
// 用最小堆可以把这一步降到 O(log n)，整体变成 O(e log n) ——
// 这就是"堆优化的 Dijkstra"。稀疏图下快很多，但代码要长一截。
// 本课程用朴素版，因为思路清楚、写起来短。

// 返回 dist 最小的未收录顶点；都收录了返回 -1
int FindMinDist(MGraph *G, int dist[], int collected[])
{
// 纪录最小的顶点和距离
    int minV = -1;
    int minDist = INF;
// 循环用
    int i;

    for (i = 0; i < G->nv; i++)
    {
// 只看还没收录的
        if (collected[i] == 0 && dist[i] < minDist)
        {
            minDist = dist[i];
            minV = i;
        }
    }

// 返回（-1 表示没有待定的了）
    return minV;
}

// 数一数图里有几条边（验证建图对不对）
int CountWeightedEdges(MGraph *G)
{
// 循环用
    int i, j;
// 计数（无向图每条边数两次，最后除以 2）
    int count = 0;

    for (i = 0; i < G->nv; i++)
    {
        for (j = 0; j < G->nv; j++)
        {
// 有边：既不是自己到自己，也不是 INF
            if (i != j && G->g[i][j] < INF)
            {
                count++;
            }
        }
    }

    return count / 2;
}

// ============ 用那个带权图走一遍 ============
//
//          0 ──2── 1
//          │       │
//          5       1
//          │       │
//          3 ──1── 2
//
// 从 0 出发。初始 dist 只看直连：dist = [0, 2, INF, 5]
//
// **第 1 轮**：未收录里最小的是 1（dist=2），收录它
//
//   用 1 松弛邻居：1 连 0（已收录，跳过）和 2（权 1）
//
//     绕 1 到 2 的距离 = dist[1] + 1 = 2 + 1 = 3 < INF  →  更新
//
//   dist = [0, 2, 3, 5]，path[2] = 1
//
// **第 2 轮**：未收录里最小的是 2（dist=3），收录它
//
//   用 2 松弛邻居：2 连 1（已收录）和 3（权 1）
//
//     绕 2 到 3 = 3 + 1 = 4 < 5  →  更新
//
//   dist = [0, 2, 3, 4]，path[3] = 2
//
// **第 3 轮**：未收录里最小的是 3（dist=4），收录它
//
//   3 的邻居都收录了，没有可松弛的
//
// **第 4 轮**：没有未收录的了 → 结束
//
// 最终：到 1 是 2，到 2 是 3，到 3 是 4
//
// 注意 3 的答案！一开始直连看着是 5，绕一圈反而更近（4）。
// 这就是"松弛"要反复做的原因 —— **第一眼看到的未必最好**。
//
// ============ 松弛这个名字 ============
//
// "松弛"（relax）的意思是：原来那个距离太"紧"了（当作最终答案），
// 现在发现可以更松（更短），于是放宽它。
//
// 判断只有一句：
//
//     if (dist[v] + G->g[v][w] < dist[w]) 更新
//
// 这句是整个算法的核心，其余都是围着它转的。

// 从源点 s 出发做 Dijkstra，结果放进 dist 和 path
void Dijkstra(MGraph *G, int s, int dist[], int path[])
{
// 收录标记
    int collected[MAXV];
// 循环用
    int i;
// 当前要收录的顶点
    int v;
// 邻居
    int w;

// 初始化三个数组
    InitDistPath(G, s, dist, path);

// 一开始只有源点被收录
// 源点到自己是 0，这个距离不用算，直接确定。
    for (i = 0; i < G->nv; i++)
    {
        collected[i] = 0;
    }
    collected[s] = 1;

// 主循环：每轮收录一个顶点
    while (1)
    {
// ① 挑出未收录里 dist 最小的
        v = FindMinDist(G, dist, collected);

// 没有待定的了 → 全部确定，结束
        if (v < 0)
        {
            break;
        }

// ② 收录它 —— 从这一刻起，dist[v] 就是最终答案
        collected[v] = 1;

// ③ 用它去松弛所有邻居
        for (w = 0; w < G->nv; w++)
        {
// 只处理：没收录的、且确实有边的
// 已经收录的不用管（它的答案定了，而且更短的路早该被它自己发现）。
            if (collected[w] == 0 && G->g[v][w] < INF)
            {
// 核心那一句：绕 v 过去会不会更近？
                if (dist[v] + G->g[v][w] < dist[w])
                {
// 更近就更新距离
                    dist[w] = dist[v] + G->g[v][w];
// 并记下 w 是从 v 过来的
                    path[w] = v;
                }
            }
        }
    }
}

// ============ path 数组记的是什么 ============
//
// path[w] = v 表示"到 w 的最短路是从 v 过来的"。
//
// 所以想知道"从源点到 w 的完整路线"，就从 w 出发一路找 path：
//
//     w → path[w] → path[path[w]] → ... → 源点
//
// 走到 path 为 -1 就说明到起点了（源点的 path 是 -1）。
//
// 但这个顺序是**倒的**。要正着输出（源点 → w），有两个办法：
//
//   ① 先倒着走一遍收集到数组里，再倒着打印
//   ② **用递归**：先递归打印"到前驱的路径"，再打印自己
//
// 这里用 ② —— 递归天然就是"先处理更深的一层，再处理自己"，
// 正好把顺序翻过来，代码还短。
//
// ============ 和二叉树后序遍历的思路一样 ============
//
// "先递归、后处理自己"这个套路，在后序遍历里出现过：
// 先处理左右子树，再处理根。
// 这里也一样：先把前缀路径打完，再打自己。

// 递归打印从源点到 v 的路径
// 调用一次打印一条完整路径（含起点和终点）
void PrintPath(int path[], int v)
{
// path[v] >= 0 说明 v 不是起点，前面还有路
    if (path[v] >= 0)
    {
// 先把前面那段打完
// 这一句递归会把整条前缀都输出完，才轮到下面两行。
        PrintPath(path, path[v]);

// 再打自己（带个箭头）
        printf(" → %d", v);
    }
// 走到起点了：它就是第一个要打印的
    else
    {
        printf("%d", v);
    }
}

// 打印所有顶点的最短距离和路径
void PrintAll(MGraph *G, int s, int dist[], int path[])
{
// 循环用
    int i;

    printf("从源点 %d 出发：\n", s);
    printf("  终点   最短距离   路径\n");
    printf("  ----   --------   ------------------\n");

    for (i = 0; i < G->nv; i++)
    {
// 跳过源点自己
        if (i == s)
        {
            continue;
        }

// 到不了的单独说明
        if (dist[i] >= INF)
        {
            printf("   %2d    %8s   不可达\n", i, "—");
            continue;
        }

// 打印距离和路径
        printf("   %2d    %8d   ", i, dist[i]);
        PrintPath(path, i);
        printf("\n");
    }
}

// ============ 这个例子特意留了个陷阱 ============
//
// 顶点 3 直连源点的权值是 5，一眼看去答案就是 5。
// 但绕 1 → 2 → 3 走一圈只要 2 + 1 + 1 = 4。
//
// 这正是 Dijkstra 要处理的情况：**初始的 dist 只是"目前已知"，不是答案**，
// 必须靠一轮轮松弛把它改小。
//
// 如果程序输出 5 而不是 4，说明松弛那一步写错了 ——
// 最常见的原因是漏了 `<` 判断，或者只更新了 dist 忘了更新 path。

// 主函数
int main(void)
{
// 带权边表：每条边 { 起点, 终点, 权值 }
// 这张图的形状：
//          0 ──2── 1
//          │       │
//          5       1
//          │       │
//          3 ──1── 2
    static const int edges[][3] = { { 0, 1, 2 }, { 0, 3, 5 }, { 1, 2, 1 }, { 2, 3, 1 } };

// 图
