modes.short:
#include <stdio.h>
#include <stdlib.h>


// 最多顶点数
#define MAXV 100

// 表示"没有边"的权值
#define INF 65535

// 带权图的邻接矩阵
typedef struct
{
// 顶点数
    int nv;
// 边数
    int ne;
// g[i][j] 是边 i→j 的权值；等于 INF 表示没有这条边
    int g[MAXV][MAXV];
} MGraph;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// 用带权边表建图
void CreateWeightedGraph(MGraph *G, int nv, const int edges[][3], int edgeCount)
{
// 循环用
    int i, j;

// 记规模
    G->nv = nv;
    G->ne = edgeCount;

// 初始化：无边的地方填 INF，对角线填 0
    for (i = 0; i < nv; i++)
    {
        for (j = 0; j < nv; j++)
        {
            G->g[i][j] = (i == j) ? 0 : INF;
        }
    }

// 逐条边填权值
    for (i = 0; i < edgeCount; i++)
    {
        int u = edges[i][0];
        int v = edges[i][1];
        int w = edges[i][2];

// 无向图两个方向都填
        G->g[u][v] = w;
        G->g[v][u] = w;
    }
}

// 初始化三个数组（供 Dijkstra 使用）
void InitDistPath(MGraph *G, int s, int dist[], int path[])
{
// 循环用
    int i;

// dist 一开始只知道源点直连的那些边
    for (i = 0; i < G->nv; i++)
    {
        dist[i] = G->g[s][i];

// path：直连的记下源点，不直连的记 -1
        if (G->g[s][i] < INF && i != s)
        {
            path[i] = s;
        }
        else
        {
            path[i] = -1;
        }
    }

// 源点到自己是 0
    dist[s] = 0;
// 源点的前驱是自己（也可以理解成"没有前驱"）
    path[s] = -1;
}


// 返回 dist 最小的未收录顶点；都收录了返回 -1
int FindMinDist(MGraph *G, int dist[], int collected[])
{
// 纪录最小的顶点和距离
    int minV = -1;
    int minDist = INF;
// 循环用
    int i;

    for (i = 0; i < G->nv; i++)
    {
// 只看还没收录的
        if (collected[i] == 0 && dist[i] < minDist)
        {
            minDist = dist[i];
            minV = i;
        }
    }

// 返回（-1 表示没有待定的了）
    return minV;
}

// 数一数图里有几条边（验证建图对不对）
int CountWeightedEdges(MGraph *G)
{
// 循环用
    int i, j;
// 计数（无向图每条边数两次，最后除以 2）
    int count = 0;

    for (i = 0; i < G->nv; i++)
    {
        for (j = 0; j < G->nv; j++)
        {
// 有边：既不是自己到自己，也不是 INF
            if (i != j && G->g[i][j] < INF)
            {
                count++;
            }
        }
    }

    return count / 2;
}


// 从源点 s 出发做 Dijkstra，结果放进 dist 和 path
void Dijkstra(MGraph *G, int s, int dist[], int path[])
{
// 收录标记
    int collected[MAXV];
// 循环用
    int i;
// 当前要收录的顶点
    int v;
// 邻居
    int w;

// 初始化三个数组
    InitDistPath(G, s, dist, path);

// 一开始只有源点被收录
    for (i = 0; i < G->nv; i++)
    {
        collected[i] = 0;
    }
    collected[s] = 1;

// 主循环：每轮收录一个顶点
    while (1)
    {
// ① 挑出未收录里 dist 最小的
        v = FindMinDist(G, dist, collected);

// 没有待定的了 → 全部确定，结束
        if (v < 0)
        {
            break;
        }

// ② 收录它 —— 从这一刻起，dist[v] 就是最终答案
        collected[v] = 1;

// ③ 用它去松弛所有邻居
        for (w = 0; w < G->nv; w++)
        {
// 只处理：没收录的、且确实有边的
            if (collected[w] == 0 && G->g[v][w] < INF)
            {
// 核心那一句：绕 v 过去会不会更近？
                if (dist[v] + G->g[v][w] < dist[w])
                {
// 更近就更新距离
                    dist[w] = dist[v] + G->g[v][w];
// 并记下 w 是从 v 过来的
                    path[w] = v;
                }
            }
        }
    }
}


// 递归打印从源点到 v 的路径
void PrintPath(int path[], int v)
{
// path[v] >= 0 说明 v 不是起点，前面还有路
    if (path[v] >= 0)
    {
// 先把前面那段打完
        PrintPath(path, path[v]);

// 再打自己（带个箭头）
        printf(" → %d", v);
    }
// 走到起点了：它就是第一个要打印的
    else
    {
        printf("%d", v);
    }
}

// 打印所有顶点的最短距离和路径
void PrintAll(MGraph *G, int s, int dist[], int path[])
{
// 循环用
    int i;

    printf("从源点 %d 出发：\n", s);
    printf("  终点   最短距离   路径\n");
    printf("  ----   --------   ------------------\n");

    for (i = 0; i < G->nv; i++)
    {
// 跳过源点自己
        if (i == s)
        {
            continue;
        }

// 到不了的单独说明
        if (dist[i] >= INF)
        {
            printf("   %2d    %8s   不可达\n", i, "—");
            continue;
        }

// 打印距离和路径
        printf("   %2d    %8d   ", i, dist[i]);
        PrintPath(path, i);
        printf("\n");
    }
}


// 主函数
int main(void)
{
// 带权边表：每条边 { 起点, 终点, 权值 }
    static const int edges[][3] = { { 0, 1, 2 }, { 0, 3, 5 }, { 1, 2, 1 }, { 2, 3, 1 } };

// 图
    MGraph G;
// 三个结果数组
    int dist[MAXV];
    int path[MAXV];
// 源点
    int s = 0;
// 循环用
    int i, j;

// 建图
    CreateWeightedGraph(&G, 4, edges, 4);

// 打印邻接矩阵
    printf("带权图的邻接矩阵（%d 表示没有边）：\n", INF);
    printf("      ");
    for (j = 0; j < G.nv; j++)
    {
        printf("%6d", j);
    }
    printf("\n");

    for (i = 0; i < G.nv; i++)
    {
        printf("  %2d [", i);
        for (j = 0; j < G.nv; j++)
        {
            if (G.g[i][j] >= INF)
            {
                printf("%6s", "INF");
            }
            else
            {
                printf("%6d", G.g[i][j]);
            }
        }
        printf(" ]\n");
    }
    printf("（数出来的边数 = %d）\n\n", CountWeightedEdges(&G));

// 跑 Dijkstra
    Dijkstra(&G, s, dist, path);

// 打印结果
    PrintAll(&G, s, dist, path);

// 重点提示
    printf("\n注意顶点 3：直连源点的权值是 5，但绕 0→1→2→3 只要 4\n");
    printf("（这就是「松弛」要反复做的原因 —— 第一眼看到的未必最好）\n\n");

// 换个源点再跑一次
    printf("=== 换个源点：从 2 出发 ===\n");
    Dijkstra(&G, 2, dist, path);
    PrintAll(&G, 2, dist, path);

// 正常结束
    return 0;
}

